mapper.sql:
select detail.*, item.item_code as item_code, item.item_name as item_name, item.unit as unit, sku.sku_name as sku_name, sku.product_identifier as product_identifier, sku.quality_grade as quality_grade, rack.rack_name as rack_name, location.location_name as location_name from wms_inventory_detail detail inner join wms_item_sku sku on detail.sku_id=sku.id inner join wms_item item on sku.item_id=item.id left join wms_rack rack on detail.rack_id = rack.id left join wms_location location on detail.location_id = location.id
and item.item_name like concat('%', #{bo.itemName}, '%')
and item.item_code like concat('%', #{bo.itemCode}, '%')
and sku.sku_name like concat('%', #{bo.skuName}, '%')
and item.id=#{bo.itemId}
and detail.warehouse_id=#{bo.warehouseId}
and detail.area_id=#{bo.areaId}
and (detail.create_time between #{bo.createStartTime} and #{bo.createEndTime})
order by detail.warehouse_id,detail.area_id,sku.item_id,sku.id,detail.create_time
